class InMemoryEventBroker {
  private partitions: { offset: number; key: string; payload: string }[][] = [];
  constructor(public numPartitions: number) {
    for (let i = 0; i < numPartitions; i++) {
      this.partitions.push([]);
    }
  }
  produce(key: string, payload: string): { partition: number; offset: number } {
    const part = key.length % this.numPartitions;
    const offset = this.partitions[part].length;
    this.partitions[part].push({ offset, key, payload });
    return { partition: part, offset };
  }
  consume(partition: number, startOffset: number, maxCount: number): { offset: number; key: string; payload: string }[] {
    if (partition < 0 || partition >= this.numPartitions) return [];
    const log = this.partitions[partition];
    return log.filter(r => r.offset >= startOffset).slice(0, maxCount);
  }
  getHighWaterMark(partition: number): number {
    if (partition < 0 || partition >= this.numPartitions) return 0;
    return this.partitions[partition].length;
  }
}

