class ConsumerGroupCoordinator {
  private offsets = new Map<string, Map<number, number>>();
  commit(groupId: string, partition: number, offset: number): void {
    if (!this.offsets.has(groupId)) this.offsets.set(groupId, new Map());
    this.offsets.get(groupId)!.set(partition, offset);
  }
  getCommitted(groupId: string, partition: number): number | null {
    const group = this.offsets.get(groupId);
    if (!group || !group.has(partition)) return null;
    return group.get(partition)!;
  }
  getGroupSummary(groupId: string): Record<number, number> {
    const group = this.offsets.get(groupId);
    if (!group) return {};
    const res: Record<number, number> = {};
    for (const [p, o] of group.entries()) {
      res[p] = o;
    }
    return res;
  }
}

stream-web-exam-day-6:
function assignPartitionsRange(numPartitions: number, consumers: string[]): Record<string, number[]> {
  if (consumers.length === 0) return {};
  const sorted = [...consumers].sort();
  const res: Record<string, number[]> = {};
  for (const c of sorted) res[c] = [];
  const base = Math.floor(numPartitions / sorted.length);
  const remainder = numPartitions % sorted.length;
  let currentPart = 0;
  for (let i = 0; i < sorted.length; i++) {
    const count = base + (i < remainder ? 1 : 0);
    for (let j = 0; j < count; j++) {
      res[sorted[i]].push(currentPart++);
    }
  }
  return res;
}

stream-web-assign-day-6:
function assignPartitionsRoundRobin(numPartitions: number, consumers: string[]): Record<string, number[]> {
  if (consumers.length === 0) return {};
  const sorted = [...consumers].sort();
  const res: Record<string, number[]> = {};
  for (const c of sorted) res[c] = [];
  for (let p = 0; p < numPartitions; p++) {
    const c = sorted[p % sorted.length];
    res[c].push(p);
  }
  return res;
}

