function calculateStickyMigrations(currentAssignment: Record<string, number[]>, newAssignment: Record<string, number[]>): { retained: Record<string, number[]>; revoked: Record<string, number[]>; assigned: Record<string, number[]> } {
  const retained: Record<string, number[]> = {};
  const revoked: Record<string, number[]> = {};
  const assigned: Record<string, number[]> = {};
  const allConsumers = new Set([...Object.keys(currentAssignment), ...Object.keys(newAssignment)]);
  for (const c of allConsumers) {
    const curParts = new Set(currentAssignment[c] || []);
    const newParts = new Set(newAssignment[c] || []);
    retained[c] = Array.from(curParts).filter(p => newParts.has(p)).sort((a, b) => a - b);
    revoked[c] = Array.from(curParts).filter(p => !newParts.has(p)).sort((a, b) => a - b);
    assigned[c] = Array.from(newParts).filter(p => !curParts.has(p)).sort((a, b) => a - b);
  }
  return { retained, revoked, assigned };
}

