class ConsumerHeartbeatTracker {
  private lastHeartbeat = new Map<string, number>();
  constructor(public sessionTimeoutMs: number) {}
  heartbeat(consumerId: string, timestampMs: number): void {
    this.lastHeartbeat.set(consumerId, timestampMs);
  }
  getDeadMembers(currentTimestampMs: number): string[] {
    const dead: string[] = [];
    for (const [id, ts] of this.lastHeartbeat.entries()) {
      if (currentTimestampMs - ts > this.sessionTimeoutMs) {
        dead.push(id);
      }
    }
    return dead.sort();
  }
}

