function evaluateDeliveryOutcome(strategy: 'at-most-once' | 'at-least-once', crashDuringProcessing: boolean): { dataLossPossible: boolean; duplicatesPossible: boolean; offsetCommitted: boolean; messageProcessed: boolean } {
  if (strategy === 'at-most-once') {
    if (crashDuringProcessing) {
      return { dataLossPossible: true, duplicatesPossible: false, offsetCommitted: true, messageProcessed: false };
    }
    return { dataLossPossible: false, duplicatesPossible: false, offsetCommitted: true, messageProcessed: true };
  } else {
    if (crashDuringProcessing) {
      return { dataLossPossible: false, duplicatesPossible: true, offsetCommitted: false, messageProcessed: false };
    }
    return { dataLossPossible: false, duplicatesPossible: false, offsetCommitted: true, messageProcessed: true };
  }
}

