class TransactionalConsumerStateStore {
  private processedIds = new Set<string>();
  private balance = 0;
  private offsets: Record<number, number> = {};
  processMessage(record: { id: string; partition: number; offset: number; amount: number }): boolean {
    if (this.processedIds.has(record.id)) {
      return false;
    }
    this.processedIds.add(record.id);
    this.balance += record.amount;
    this.offsets[record.partition] = record.offset + 1;
    return true;
  }
  getBalance(): number {
    return this.balance;
  }
  getPartitionOffsets(): Record<number, number> {
    return { ...this.offsets };
  }
}

