class BoundedFlowBuffer<T> {
  private queue: T[] = [];
  private paused = false;
  constructor(public capacity: number, public highWatermarkRatio: number = 0.8, public lowWatermarkRatio: number = 0.4) {} 
  enqueue(item: T): boolean {
    if (this.queue.length >= this.capacity) return false;
    this.queue.push(item);
    if (this.queue.length >= this.capacity * this.highWatermarkRatio) {
      this.paused = true;
    }
    return true;
  }
  dequeue(): T | null {
    if (this.queue.length === 0) return null;
    const item = this.queue.shift()!;
    if (this.queue.length <= this.capacity * this.lowWatermarkRatio) {
      this.paused = false;
    }
    return item;
  }
  isPaused(): boolean {
    return this.paused;
  }
  size(): number {
    return this.queue.length;
  }
}

