function tuneBatchSize(currentBatchSize: number, queueDepth: number, minBatch: number = 10, maxBatch: number = 1000): number {
  let next = currentBatchSize;
  if (queueDepth > 500) {
    next = Math.ceil(currentBatchSize * 1.2);
  } else if (queueDepth < 50) {
    next = Math.floor(currentBatchSize * 0.8);
  }
  return Math.min(maxBatch, Math.max(minBatch, next));
}

stream-web-exam-day-13:
function evaluateStreamCompression(rawSizeBytes: number, compressedSizeBytes: number, durationMs: number): { ratio: number; spaceSavingsPercent: number; throughputMBps: number } {
  if (rawSizeBytes <= 0 || compressedSizeBytes <= 0 || durationMs <= 0) {
    return { ratio: 1, spaceSavingsPercent: 0, throughputMBps: 0 };
  }
  const ratio = Math.round((rawSizeBytes / compressedSizeBytes) * 100) / 100;
  const spaceSavingsPercent = Math.round((1 - compressedSizeBytes / rawSizeBytes) * 100 * 100) / 100;
  const rawMB = rawSizeBytes / (1024 * 1024);
  const sec = durationMs / 1000;
  const throughputMBps = Math.round((rawMB / sec) * 100) / 100;
  return { ratio, spaceSavingsPercent, throughputMBps };
}

stream-web-assign-day-13:
function selectCompressionCodec(criteria: { target: 'max_throughput' | 'min_bandwidth' | 'balanced'; networkCostPerGb: number }): 'lz4' | 'snappy' | 'zstd' | 'gzip' {
  if (criteria.target === 'max_throughput') return 'lz4';
  if (criteria.target === 'min_bandwidth') return 'zstd';
  return criteria.networkCostPerGb > 0.05 ? 'zstd' : 'snappy';
}

