function applyStreamLittlesLaw(arrivalRateMsgPerSec: number, avgLatencyMs: number): { inFlightMessages: number; recommendedQueueCapacity: number } {
  const inFlightMessages = Math.round(arrivalRateMsgPerSec * (avgLatencyMs / 1000) * 100) / 100;
  const recommendedQueueCapacity = Math.ceil(inFlightMessages * 2);
  return { inFlightMessages, recommendedQueueCapacity };
}

stream-web-assign-day-14:
function calculateStreamBdp(bandwidthGbps: number, roundTripTimeMs: number): { bdpBytes: number; optimalBufferKilobytes: number } {
  const bytesPerSec = (bandwidthGbps * 1e9) / 8;
  const rttSec = roundTripTimeMs / 1000;
  const bdpBytes = Math.round(bytesPerSec * rttSec);
  const optimalBufferKilobytes = Math.ceil(bdpBytes / 1024);
  return { bdpBytes, optimalBufferKilobytes };
}

