class IngestPipelineEngine {
  private queue: { id: string; payload: string }[] = [];
  private throttled = false;
  constructor(public capacity: number, public batchLimit: number) {} 
  ingest(record: { id: string; payload: string }): { accepted: boolean; queueDepth: number; throttled: boolean } {
    if (this.queue.length >= this.capacity) {
      return { accepted: false, queueDepth: this.queue.length, throttled: true };
    }
    this.queue.push(record);
    if (this.queue.length >= this.capacity * 0.75) {
      this.throttled = true;
    }
    return { accepted: true, queueDepth: this.queue.length, throttled: this.throttled };
  }
  drainBatch(): { id: string; payload: string }[] {
    const batch = this.queue.splice(0, this.batchLimit);
    if (this.queue.length < this.capacity * 0.25) {
      this.throttled = false;
    }
    return batch;
  }
  isThrottled(): boolean {
    return this.throttled;
  }
}

stream-web-assign-day-15:
function computePipelineTelemetry(totalEvents: number, durationSec: number, latenciesMs: number[]): { throughputEventsPerSec: number; p50LatencyMs: number; p95LatencyMs: number; p99LatencyMs: number } {
  const throughputEventsPerSec = durationSec > 0 ? Math.round((totalEvents / durationSec) * 100) / 100 : 0;
  if (latenciesMs.length === 0) {
    return { throughputEventsPerSec, p50LatencyMs: 0, p95LatencyMs: 0, p99LatencyMs: 0 };
  }
  const sorted = [...latenciesMs].sort((a, b) => a - b);
  const getP = (p: number) => {
    const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
    return sorted[idx];
  };
  return {
    throughputEventsPerSec,
    p50LatencyMs: getP(50),
    p95LatencyMs: getP(95),
    p99LatencyMs: getP(99)
  };
}

