function transformStream<T, U>(stream: T[], mapper?: (item: T) => U, predicate?: (item: T) => boolean, flatMapper?: (item: T) => U[]): U[] {
  let filtered = stream;
  if (predicate) {
    filtered = filtered.filter(predicate);
  }
  if (flatMapper) {
    return filtered.flatMap(flatMapper);
  }
  if (mapper) {
    return filtered.map(mapper);
  }
  return filtered as unknown as U[];
}

stream-web-assign-day-16:
function branchStream<T>(events: T[], predicates: ((item: T) => boolean)[]): T[][] {
  const branches: T[][] = [];
  for (let i = 0; i <= predicates.length; i++) {
    branches.push([]);
  }
  for (const item of events) {
    let matched = false;
    for (let p = 0; p < predicates.length; p++) {
      if (predicates[p](item)) {
        branches[p].push(item);
        matched = true;
        break;
      }
    }
    if (!matched) {
      branches[predicates.length].push(item);
    }
  }
  return branches;
}

stream-web-exam-day-17:
function aggregateTumblingWindows(events: { timestamp: number; value: number }[], windowDurationMs: number): { windowStart: number; windowEnd: number; count: number; sum: number }[] {
  if (windowDurationMs <= 0 || events.length === 0) return [];
  const map = new Map<number, { count: number; sum: number }>();
  for (const e of events) {
    const start = e.timestamp - (e.timestamp % windowDurationMs);
    const existing = map.get(start) || { count: 0, sum: 0 };
    existing.count++;
    existing.sum += e.value;
    map.set(start, existing);
  }
  const starts = Array.from(map.keys()).sort((a, b) => a - b);
  return starts.map(start => {
    const agg = map.get(start)!;
    return {
      windowStart: start,
      windowEnd: start + windowDurationMs,
      count: agg.count,
      sum: agg.sum
    };
  });
}

stream-web-assign-day-17:
function aggregateKeyedTumblingWindows(events: { key: string; timestamp: number; value: number }[], windowDurationMs: number): { key: string; windowStart: number; count: number; avg: number }[] {
  if (windowDurationMs <= 0 || events.length === 0) return [];
  const map = new Map<string, { key: string; windowStart: number; count: number; sum: number }>();
  for (const e of events) {
    const start = e.timestamp - (e.timestamp % windowDurationMs);
    const mapKey = `${e.key}#${start}`;
    const existing = map.get(mapKey) || { key: e.key, windowStart: start, count: 0, sum: 0 };
    existing.count++;
    existing.sum += e.value;
    map.set(mapKey, existing);
  }
  const list = Array.from(map.values()).map(it => ({
    key: it.key,
    windowStart: it.windowStart,
    count: it.count,
    avg: Math.round((it.sum / it.count) * 100) / 100
  }));
  return list.sort((a, b) => {
    if (a.windowStart !== b.windowStart) return a.windowStart - b.windowStart;
    return a.key.localeCompare(b.key);
  });
}

stream-web-exam-day-18:
function getSlidingWindowBuckets(eventTimestamp: number, windowDurationMs: number, slideIntervalMs: number): { windowStart: number; windowEnd: number }[] {
  if (windowDurationMs <= 0 || slideIntervalMs <= 0) return [];
  const latestStart = eventTimestamp - (eventTimestamp % slideIntervalMs);
  const earliestStart = Math.max(0, eventTimestamp - windowDurationMs + 1);
  const roundedEarliest = earliestStart - (earliestStart % slideIntervalMs);
  const windows: { windowStart: number; windowEnd: number }[] = [];
  for (let s = roundedEarliest; s <= latestStart; s += slideIntervalMs) {
    if (s <= eventTimestamp && eventTimestamp < s + windowDurationMs) {
      windows.push({ windowStart: s, windowEnd: s + windowDurationMs });
    }
  }
  return windows;
}

stream-web-assign-day-18:
function computeSlidingWindowAggregates(events: { timestamp: number; value: number }[], windowDurationMs: number, slideIntervalMs: number): { windowStart: number; count: number; sum: number; max: number }[] {
  if (events.length === 0 || windowDurationMs <= 0 || slideIntervalMs <= 0) return [];
  const map = new Map<number, { count: number; sum: number; max: number }>();
  for (const e of events) {
    const latestStart = e.timestamp - (e.timestamp % slideIntervalMs);
    const earliestStart = Math.max(0, e.timestamp - windowDurationMs + 1);
    const roundedEarliest = earliestStart - (earliestStart % slideIntervalMs);
    for (let s = roundedEarliest; s <= latestStart; s += slideIntervalMs) {
      if (s <= e.timestamp && e.timestamp < s + windowDurationMs) {
        const cur = map.get(s) || { count: 0, sum: 0, max: -Infinity };
        cur.count++;
        cur.sum += e.value;
        cur.max = Math.max(cur.max, e.value);
        map.set(s, cur);
      }
    }
  }
  const starts = Array.from(map.keys()).sort((a, b) => a - b);
  return starts.map(s => {
    const it = map.get(s)!;
    return { windowStart: s, count: it.count, sum: it.sum, max: it.max };
  });
}

stream-web-exam-day-19:
function groupIntoSessionWindows(timestamps: number[], inactivityGapMs: number): { sessionStart: number; sessionEnd: number; eventCount: number }[] {
  if (timestamps.length === 0) return [];
  const sorted = [...timestamps].sort((a, b) => a - b);
  const sessions: { sessionStart: number; sessionEnd: number; eventCount: number }[] = [];
  let curStart = sorted[0];
  let curEnd = sorted[0];
  let count = 1;
  for (let i = 1; i < sorted.length; i++) {
    const t = sorted[i];
    if (t - curEnd <= inactivityGapMs) {
      curEnd = t;
      count++;
    } else {
      sessions.push({ sessionStart: curStart, sessionEnd: curEnd, eventCount: count });
      curStart = t;
      curEnd = t;
      count = 1;
    }
  }
  sessions.push({ sessionStart: curStart, sessionEnd: curEnd, eventCount: count });
  return sessions;
}

