class WatermarkManager {
  private watermark = 0;
  constructor(public maxLatenessMs: number) {} 
  onEvent(eventTimeMs: number): { watermark: number; isLate: boolean } {
    const isLate = eventTimeMs < this.watermark;
    if (!isLate) {
      const candidate = eventTimeMs - this.maxLatenessMs;
      if (candidate > this.watermark) {
        this.watermark = candidate;
      }
    }
    return { watermark: this.watermark, isLate };
  }
  getWatermark(): number {
    return this.watermark;
  }
}

