class ChangelogBackedStateStore {
  private state = new Map<string, string>();
  private changelog: { offset: number; key: string; value: string | null }[] = [];
  put(key: string, value: string): { offset: number; key: string; value: string } {
    this.state.set(key, value);
    const entry = { offset: this.changelog.length, key, value };
    this.changelog.push(entry);
    return entry;
  }
  get(key: string): string | null {
    return this.state.has(key) ? this.state.get(key)! : null;
  }
  delete(key: string): { offset: number; key: string; value: null } {
    this.state.delete(key);
    const entry = { offset: this.changelog.length, key, value: null };
    this.changelog.push(entry);
    return entry;
  }
  getChangelog(): { offset: number; key: string; value: string | null }[] {
    return [...this.changelog];
  }
}

