function compactEventLog(records: { offset: number; key: string; value: string | null }[]): { offset: number; key: string; value: string }[] {
  const latestByKey = new Map<string, { offset: number; key: string; value: string | null }>();
  for (const r of records) {
    latestByKey.set(r.key, r);
  }
  const retained: { offset: number; key: string; value: string }[] = [];
  for (const r of latestByKey.values()) {
    if (r.value !== null) {
      retained.push({ offset: r.offset, key: r.key, value: r.value });
    }
  }
  return retained.sort((a, b) => a.offset - b.offset);
}

