function materializeKTable(stream: { key: string; delta: number }[]): Record<string, number> {
  const table: Record<string, number> = {};
  for (const item of stream) {
    table[item.key] = (table[item.key] || 0) + item.delta;
    if (table[item.key] === 0) {
      delete table[item.key];
    }
  }
  return table;
}

