function joinTemporalTable(stream: { eventId: string; entityId: string; timestamp: number }[], dimensionVersions: { entityId: string; validFrom: number; validTo: number; status: string }[]): { eventId: string; status: string | null }[] {
  return stream.map(ev => {
    const match = dimensionVersions.find(d => d.entityId === ev.entityId && ev.timestamp >= d.validFrom && ev.timestamp < d.validTo);
    return {
      eventId: ev.eventId,
      status: match ? match.status : null
    };
  });
}

stream-web-exam-day-24:
function joinStreamStream(leftStream: { key: string; timestamp: number; payload: string }[], rightStream: { key: string; timestamp: number; payload: string }[], windowMs: number): { key: string; leftPayload: string; rightPayload: string; timeDeltaMs: number }[] {
  const matches: { key: string; leftPayload: string; rightPayload: string; timeDeltaMs: number }[] = [];
  for (const l of leftStream) {
    for (const r of rightStream) {
      if (l.key === r.key) {
        const delta = Math.abs(l.timestamp - r.timestamp);
        if (delta <= windowMs) {
          matches.push({
            key: l.key,
            leftPayload: l.payload,
            rightPayload: r.payload,
            timeDeltaMs: delta
          });
        }
      }
    }
  }
  return matches;
}

