class CheckpointedStreamProcessor {
  private state: Record<string, number> = {};
  private lastOffset = -1;
  private recordsSinceCheckpoint = 0;
  private lastSnapshot = { lastOffset: -1, state: {} as Record<string, number> };
  constructor(public checkpointIntervalRecords: number) {} 
  process(record: { offset: number; key: string; value: number }): { committedCheckpoint: boolean; currentTotal: number } {
    this.state[record.key] = (this.state[record.key] || 0) + record.value;
    this.lastOffset = record.offset;
    this.recordsSinceCheckpoint++;
    let committedCheckpoint = false;
    if (this.recordsSinceCheckpoint >= this.checkpointIntervalRecords) {
      this.lastSnapshot = {
        lastOffset: this.lastOffset,
        state: { ...this.state }
      };
      this.recordsSinceCheckpoint = 0;
      committedCheckpoint = true;
    }
    const currentTotal = Object.values(this.state).reduce((sum, v) => sum + v, 0);
    return { committedCheckpoint, currentTotal };
  }
  restoreFromCheckpoint(snapshot: { lastOffset: number; state: Record<string, number> }): void {
    this.lastOffset = snapshot.lastOffset;
    this.state = { ...snapshot.state };
    this.lastSnapshot = {
      lastOffset: snapshot.lastOffset,
      state: { ...snapshot.state }
    };
    this.recordsSinceCheckpoint = 0;
  }
  getCheckpointSnapshot(): { lastOffset: number; state: Record<string, number> } {
    return {
      lastOffset: this.lastSnapshot.lastOffset,
      state: { ...this.lastSnapshot.state }
    };
  }
}

stream-web-assign-day-25:
function recoverProcessorState(snapshot: { lastOffset: number; state: Record<string, number> }, changelogTail: { offset: number; key: string; delta: number }[]): { finalOffset: number; state: Record<string, number> } {
  const state: Record<string, number> = { ...snapshot.state };
  let finalOffset = snapshot.lastOffset;
  for (const entry of changelogTail) {
    if (entry.offset > snapshot.lastOffset) {
      state[entry.key] = (state[entry.key] || 0) + entry.delta;
      if (entry.offset > finalOffset) {
        finalOffset = entry.offset;
      }
    }
  }
  return { finalOffset, state };
}

stream-web-exam-day-26:
function validateSchemaEvolution(prevFields: { name: string; type: string; hasDefault: boolean }[], nextFields: { name: string; type: string; hasDefault: boolean }[], mode: 'BACKWARD' | 'FORWARD'): { compatible: boolean; reason: string } {
  const prevMap = new Map(prevFields.map(f => [f.name, f]));
  const nextMap = new Map(nextFields.map(f => [f.name, f]));
  for (const [name, pf] of prevMap.entries()) {
    if (nextMap.has(name)) {
      const nf = nextMap.get(name)!;
      if (pf.type !== nf.type) {
        return { compatible: false, reason: `Type changed for field ${name}` };
      }
    }
  }
  if (mode === 'BACKWARD') {
    for (const [name, nf] of nextMap.entries()) {
      if (!prevMap.has(name) && !nf.hasDefault) {
        return { compatible: false, reason: `New field ${name} must have a default value` };
      }
    }
  } else if (mode === 'FORWARD') {
    for (const [name, pf] of prevMap.entries()) {
      if (!nextMap.has(name) && !pf.hasDefault) {
        return { compatible: false, reason: `Deleted field ${name} must have had a default value` };
      }
    }
  }
  return { compatible: true, reason: 'COMPATIBLE' };
}

