function findReplayStartOffsets(partitionLogs: Record<number, { offset: number; timestamp: number }[]>, replayTimestamp: number): Record<number, number> {
  const result: Record<number, number> = {};
  for (const [partStr, entries] of Object.entries(partitionLogs)) {
    const part = Number(partStr);
    if (!entries || entries.length === 0) {
      result[part] = 0;
      continue;
    }
    const match = entries.find(e => e.timestamp >= replayTimestamp);
    result[part] = match ? match.offset : entries.length;
  }
  return result;
}

