function predictTimeToRecoverSeconds(currentLag: number, consumptionRateMsgPerSec: number, productionRateMsgPerSec: number): { willRecover: boolean; recoverySeconds: number | null; netDrainRateMsgPerSec: number } {
  const netDrainRateMsgPerSec = consumptionRateMsgPerSec - productionRateMsgPerSec;
  if (currentLag <= 0) {
    return { willRecover: true, recoverySeconds: 0, netDrainRateMsgPerSec };
  }
  if (netDrainRateMsgPerSec <= 0) {
    return { willRecover: false, recoverySeconds: null, netDrainRateMsgPerSec };
  }
  const recoverySeconds = Math.ceil(currentLag / netDrainRateMsgPerSec);
  return { willRecover: true, recoverySeconds, netDrainRateMsgPerSec };
}

stream-web-assign-day-29:
function detectPartitionHotspots(partitionMessageCounts: Record<number, number>, hotspotThresholdRatio: number = 2.0): { hasHotspot: boolean; averageMessages: number; hotspotPartitions: number[] } {
  const parts = Object.keys(partitionMessageCounts).map(Number);
  if (parts.length === 0) {
    return { hasHotspot: false, averageMessages: 0, hotspotPartitions: [] };
  }
  const total = parts.reduce((sum, p) => sum + partitionMessageCounts[p], 0);
  const averageMessages = Math.round((total / parts.length) * 100) / 100;
  const cutoff = averageMessages * hotspotThresholdRatio;
  const hotspotPartitions = parts.filter(p => partitionMessageCounts[p] >= cutoff).sort((a, b) => a - b);
  return {
    hasHotspot: hotspotPartitions.length > 0,
    averageMessages,
    hotspotPartitions
  };
}

