class FinancialFraudDetector {
  private history = new Map<string, { timestampMs: number; amount: number }[]>();
  constructor(public velocityWindowMs: number, public maxCountPerWindow: number, public maxTotalSpendPerWindow: number) {} 
  processTransaction(tx: { id: string; cardId: string; timestampMs: number; amount: number }): { flagged: boolean; reason: 'VELOCITY_COUNT_EXCEEDED' | 'VELOCITY_SPEND_EXCEEDED' | 'CLEAN' } {
    let list = this.history.get(tx.cardId) || [];
    list = list.filter(item => tx.timestampMs - item.timestampMs < this.velocityWindowMs);
    list.push({ timestampMs: tx.timestampMs, amount: tx.amount });
    this.history.set(tx.cardId, list);
    const count = list.length;
    const totalSpend = list.reduce((sum, item) => sum + item.amount, 0);
    if (count > this.maxCountPerWindow) {
      return { flagged: true, reason: 'VELOCITY_COUNT_EXCEEDED' };
    }
    if (totalSpend > this.maxTotalSpendPerWindow) {
      return { flagged: true, reason: 'VELOCITY_SPEND_EXCEEDED' };
    }
    return { flagged: false, reason: 'CLEAN' };
  }
  getActiveCardVelocity(cardId: string, nowMs: number): { count: number; totalSpend: number } {
    const list = (this.history.get(cardId) || []).filter(item => nowMs - item.timestampMs < this.velocityWindowMs);
    const count = list.length;
    const totalSpend = list.reduce((sum, item) => sum + item.amount, 0);
    return { count, totalSpend };
  }
}

